const lane = ["a", "b", "c", "d", "e"];

for (let i = 0; i < lane.length; i++) {
  if (lane[i] === "b" || lane[i] === "c") lane.splice(i, 1);
}
console.log(lane.join(""));

const out = lane.reverse().splice(1, 1, "x", "y");
console.log(out.join(""));
